begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(relrowsecurity,'RLS on '||relname) from pg_class where oid in ('public.checkout_attempts'::regclass,'public.payment_receipts'::regclass,'public.payment_events'::regclass) order by relname;
select ok(not has_table_privilege('authenticated','public.checkout_attempts','INSERT'),'Clients cannot create checkout attempts directly');
select ok(not has_table_privilege('authenticated','public.payment_receipts','SELECT'),'Receipts have no client table grant');
select ok(not has_table_privilege('anon','public.payment_events','SELECT'),'Webhook inbox is private');
select ok(has_function_privilege('authenticated','public.prepare_checkout(uuid,text)','EXECUTE'),'Signed-in renters may request consented checkout');
select ok(has_function_privilege('authenticated','public.get_checkout(uuid)','EXECUTE'),'Participants have a safe status function');
select ok(not has_function_privilege('anon','public.prepare_checkout(uuid,text)','EXECUTE'),'Anonymous checkout denied');
select ok(not has_function_privilege('authenticated','public.sync_checkout(uuid,uuid,jsonb)','EXECUTE'),'Clients cannot mark paid');
select ok(not has_function_privilege('authenticated','public.claim_payment_work(uuid,integer)','EXECUTE'),'Clients cannot claim provider work');
select ok(not has_function_privilege('authenticated','public.enqueue_payment_event(text,text,uuid,text)','EXECUTE'),'Clients cannot forge webhook receipt');
select ok(not has_function_privilege('authenticated','public.checkout_payload(public.checkout_attempts)','EXECUTE'),'Private payload helper is not an RPC');
select ok(has_function_privilege('service_role','public.sync_checkout(uuid,uuid,jsonb)','EXECUTE'),'Only trusted worker can persist provider truth');
select ok(not has_function_privilege('authenticated','public.checkout_can_pay(uuid)','EXECUTE'),'Private preflight cannot be used to probe other bookings');
select ok(has_function_privilege('service_role','public.checkout_can_pay(uuid)','EXECUTE'),'Worker can check eligibility before external work');
grant select,insert,update,delete on public.checkout_attempts,public.payment_receipts,public.payment_events to authenticated,anon;
set local role authenticated;
select is((select count(*) from public.checkout_attempts),0::bigint,'Accidental SELECT grant does not bypass deny-all RLS');
select throws_ok($$insert into public.payment_events(event_id,session_id,body_hash,state) values('evt_forged','cs_forged',repeat('a',64),'queued')$$,'42501',null::text,'Accidental INSERT grant cannot forge provider events');
select throws_ok($$select public.sync_checkout(gen_random_uuid(),gen_random_uuid(),'{}')$$,'42501',null::text,'Untrusted success RPC denied');
select throws_ok($$select public.prepare_checkout(gen_random_uuid(),'demo-payments-v1')$$,'42501','profile_required','Missing active verified identity denied');
reset role;
select * from finish();
rollback;
